import { scope } from "arktype";

const myScope = scope({
  "db.config": {
    host: "string",
    port: "number"
  },
  "http.server": {
    port: "number",
    db: "db.config"
  }
});

const module = myScope.export();

// Test it ourselves
try {
  module.db.config.assert({ host: "localhost", port: 5432 });
  module.http.server.assert({ port: 8080, db: { host: "localhost", port: 5432 } });

  let rejected = false;
  try {
    module.http.server.assert({ port: 8080, db: { host: "localhost", port: "5432" } });
  } catch (e) {
    rejected = true;
  }
  if (!rejected) throw new Error("Should have rejected");

  console.log("Success");
} catch (e) {
  console.error("Failed", e);
  process.exit(1);
}

export default module;

