});

const module = myScope.export();

type Submodules = {
  db: { config: typeof module["db.config"] };
  http: { server: typeof module["http.server"] };
};

const exportedModule = Object.assign(module, {
  db: { config: module["db.config"] },
  http: { server: module["http.server"] }
}) as typeof module & Submodules;

export default exportedModule;

